import { writeFile } from "node:fs/promises"
import { storageTables, tableDdl } from "./proposal-storage-schema.ts"
const sql =
	"-- Generated by write-storage-schema.mjs; edit proposal-storage-schema.ts instead.\n-- Empty-store installation only. No automatic migration or reset of legacy tables.\n\n" +
	storageTables.map((t) => tableDdl(t, 2) + ";").join("\n\n") +
	"\n"
await writeFile(new URL("./schema.sql", import.meta.url), sql)
console.log("Wrote explicit DDL for " + storageTables.length + " tables")
